import unittest
from delivery_bind import bind_delivery

class DeliveryBinding(unittest.TestCase):
    def test_later_positional_arguments_follow_saved_arguments(self):
        def pack(a, b, c):
            return a, b, c
        bound = bind_delivery(pack, 'warehouse', 'west')
        self.assertEqual(bound('dock'), ('warehouse', 'west', 'dock'))

    def test_later_keywords_override_without_changing_saved_defaults(self):
        def label(prefix, lane, *, suffix=''):
            return prefix + '/' + lane + suffix
        bound = bind_delivery(label, 'zone', suffix=':base')
        self.assertEqual(bound('west', suffix=':urgent'), 'zone/west:urgent')
        self.assertEqual(bound('east'), 'zone/east:base')
        self.assertEqual(bound(lane='north'), 'zone/north:base')

    def test_new_keywords_extend_defaults(self):
        def options(**kwargs):
            return kwargs
        bound = bind_delivery(options, mode='road')
        self.assertEqual(bound(priority=2), {'mode': 'road', 'priority': 2})
        self.assertEqual(bound(mode='rail'), {'mode': 'rail'})
        self.assertEqual(bound(), {'mode': 'road'})

if __name__ == '__main__':
    unittest.main()

